exercise.solution:
CREATE UNIQUE INDEX accounts_live_handle_uq
  ON accounts (lower(handle))
  WHERE deleted_at IS NULL;

exercise.check:
CREATE TEMP TABLE probe_log (probe text, outcome text);
DO $$
DECLARE target int;
BEGIN
  SELECT a.id INTO target FROM accounts a
  WHERE a.id < 900 AND a.deleted_at IS NOT NULL
    AND EXISTS (SELECT 1 FROM accounts b WHERE b.id < 900 AND b.deleted_at IS NULL AND lower(b.handle) = lower(a.handle))
  ORDER BY a.id LIMIT 1;
  IF target IS NULL THEN
    INSERT INTO probe_log VALUES ('restore taken handle', 'no candidate');
  ELSE
    BEGIN
      UPDATE accounts SET deleted_at = NULL WHERE id = target;
      INSERT INTO probe_log VALUES ('restore taken handle', 'allowed');
    EXCEPTION WHEN unique_violation OR exclusion_violation THEN
      INSERT INTO probe_log VALUES ('restore taken handle', 'rejected');
    END;
  END IF;
  BEGIN
    INSERT INTO accounts VALUES (901, 'ProbeX', NULL), (902, 'probex', NULL);
    INSERT INTO probe_log VALUES ('live clash, other case', 'allowed');
  EXCEPTION WHEN unique_violation OR exclusion_violation THEN
    INSERT INTO probe_log VALUES ('live clash, other case', 'rejected');
  END;
  BEGIN
    INSERT INTO accounts VALUES (903, 'ProbeW', NULL), (904, 'ProbeW', NULL);
    INSERT INTO probe_log VALUES ('live clash, same case', 'allowed');
  EXCEPTION WHEN unique_violation OR exclusion_violation THEN
    INSERT INTO probe_log VALUES ('live clash, same case', 'rejected');
  END;
  BEGIN
    INSERT INTO accounts VALUES (905, 'ProbeY', NULL), (906, 'PROBEY', '2026-01-01');
    INSERT INTO probe_log VALUES ('closed copy of live handle', 'allowed');
  EXCEPTION WHEN unique_violation OR exclusion_violation THEN
    INSERT INTO probe_log VALUES ('closed copy of live handle', 'rejected');
  END;
  BEGIN
    INSERT INTO accounts VALUES (907, 'ProbeZ', '2026-01-01'), (908, 'probez', '2026-02-01');
    INSERT INTO probe_log VALUES ('two closed copies', 'allowed');
  EXCEPTION WHEN unique_violation OR exclusion_violation THEN
    INSERT INTO probe_log VALUES ('two closed copies', 'rejected');
  END;
  BEGIN
    INSERT INTO accounts VALUES (909, 'ProbeV', NULL), (910, 'ProbeU', NULL);
    INSERT INTO probe_log VALUES ('different live handles', 'allowed');
  EXCEPTION WHEN unique_violation OR exclusion_violation THEN
    INSERT INTO probe_log VALUES ('different live handles', 'rejected');
  END;
END $$;
SELECT probe, outcome FROM probe_log
UNION ALL
SELECT 'existing rows kept', count(*)::text FROM accounts WHERE id < 900;
